'use strict';
window.TDNCodeAssist=(()=>{
  const core=window.TDNCodeAssistCore,checkbox=document.querySelector('#codeAssistEnabled');
  let enabled=false,data=null,loading=null,input=null,analysis=null,selected=0,timer=null;
  try{enabled=localStorage.getItem('tdn-code-assist')==='true';}catch{}
  checkbox.checked=enabled;
  const panel=document.createElement('div');panel.className='code-assist-panel';panel.hidden=true;panel.setAttribute('role','region');panel.setAttribute('aria-label','Gợi ý code và tham số');document.body.append(panel);
  function hide(){panel.hidden=true;input?.removeAttribute('aria-controls');input?.removeAttribute('aria-expanded');analysis=null;}
  function python(target){if(!(target instanceof HTMLTextAreaElement)||target.disabled)return false;if(target.id==='codeEditor')return typeof state!=='undefined'&&state.activeFile.endsWith('.py');return target.dataset.language==='code';}
  async function catalog(){if(data)return data;if(!loading)loading=fetch('code-assist-data.json').then(response=>{if(!response.ok)throw Error('Không tải được chỉ mục thư viện.');return response.json();}).then(value=>data=core.prepare(value)).catch(error=>{loading=null;throw error;});return loading;}
  function caret(target){const rect=target.getBoundingClientRect(),style=getComputedStyle(target),mirror=document.createElement('div');for(const property of ['fontFamily','fontSize','fontWeight','lineHeight','letterSpacing','tabSize','padding','border','boxSizing','whiteSpace'])mirror.style[property]=style[property];Object.assign(mirror.style,{position:'fixed',visibility:'hidden',left:rect.left+'px',top:rect.top+'px',width:rect.width+'px',height:'auto',overflow:'visible'});mirror.textContent=target.value.slice(0,target.selectionStart);const marker=document.createElement('span');marker.textContent='|';mirror.append(marker);document.body.append(mirror);const point=marker.getBoundingClientRect();mirror.remove();return {left:Math.max(rect.left,point.left-target.scrollLeft),top:Math.max(rect.top,Math.min(rect.bottom,point.bottom-target.scrollTop))};}
  function position(){if(!input||panel.hidden)return;const point=caret(input),width=Math.min(610,window.innerWidth-24);panel.style.width=width+'px';panel.style.left=Math.max(8,Math.min(window.innerWidth-width-8,point.left))+'px';const height=Math.min(panel.scrollHeight,330);panel.style.top=(point.top+height+10<window.innerHeight?point.top+6:Math.max(8,point.top-height-25))+'px';}
  function paint(){panel.replaceChildren();input?.removeAttribute('aria-controls');input?.removeAttribute('aria-expanded');if(!analysis)return;
    if(analysis.signature){const info=analysis.signature,signature=document.createElement('div');signature.className='assist-signature';const name=document.createElement('strong');name.textContent=info.name+'(';signature.append(name);info.params.forEach((param,index)=>{if(index)signature.append(document.createTextNode(', '));const span=document.createElement('span');span.className=param.name===info.active?'assist-active-param':'';span.textContent=param.name+(param.default===null?'':'='+param.default);signature.append(span);});signature.append(document.createTextNode(')'));panel.append(signature);if(info.caseMismatch){const note=document.createElement('div');note.className='assist-case-note';note.textContent='Tên đúng: '+info.canonical+' · Python phân biệt chữ hoa/thường.';panel.append(note);}}
    if(analysis.items.length){const list=document.createElement('div');list.className='assist-items';list.id='codeAssistItems';list.setAttribute('role','listbox');analysis.items.forEach((item,index)=>{const row=document.createElement('button');row.type='button';row.className='assist-item'+(index===selected?' selected':'');row.setAttribute('role','option');row.setAttribute('aria-selected',String(index===selected));const label=document.createElement('span');label.textContent=item.label;const detail=document.createElement('small');detail.textContent=item.detail;row.append(label,detail);row.onpointerdown=event=>{event.preventDefault();apply(index);};row.onpointerenter=()=>{selected=index;list.querySelectorAll('button').forEach((button,i)=>{button.classList.toggle('selected',i===index);button.setAttribute('aria-selected',String(i===index));});};list.append(row);});panel.append(list);input.setAttribute('aria-controls','codeAssistItems');input.setAttribute('aria-expanded','true');}
    const help=document.createElement('div');help.className='assist-help';help.textContent='↑↓ chọn · Tab/Enter chèn · Esc đóng · Ctrl+Space mở';panel.append(help);panel.hidden=false;position();
  }
  async function update(target){if(!enabled||!python(target))return hide();try{const index=await catalog();if(!enabled||document.activeElement!==target)return;if(input&&input!==target){input.removeAttribute('aria-controls');input.removeAttribute('aria-expanded');}input=target;const context=target.id==='codeEditor'?target.value:(window.TDNNotebookUI.sourceContext?.()||target.value);analysis=core.analyze(target.value,target.selectionStart,index,context);selected=0;if(!analysis.items.length&&!analysis.signature)return hide();paint();}catch(error){hide();checkbox.title=error.message;}}
  function apply(index){const item=analysis?.items[index];if(!input||!item)return;const target=input;target.focus();target.setRangeText(item.insert,item.from,item.to,'end');target.dispatchEvent(new Event('input',{bubbles:true}));hide();void update(target);}
  checkbox.addEventListener('change',()=>{enabled=checkbox.checked;try{localStorage.setItem('tdn-code-assist',String(enabled));}catch{}if(!enabled){clearTimeout(timer);hide();return;}checkbox.title='Đang nạp chỉ mục thư viện…';void catalog().then(()=>{checkbox.title='Gợi ý thư viện đã cài · Ctrl+Space';if(python(document.activeElement))void update(document.activeElement);}).catch(error=>{enabled=false;checkbox.checked=false;try{localStorage.setItem('tdn-code-assist','false');}catch{}checkbox.title=error.message;if(typeof toast==='function')toast(error.message);});});
  document.addEventListener('input',event=>{if(!enabled||!python(event.target))return;clearTimeout(timer);timer=setTimeout(()=>update(event.target),90);});
  document.addEventListener('click',event=>{if(!enabled)return;if(python(event.target)){void update(event.target);}else if(!panel.contains(event.target))hide();});
  document.addEventListener('focusout',event=>{if(event.target===input)setTimeout(()=>{if(document.activeElement!==input&&!panel.contains(document.activeElement))hide();},0);});
  document.addEventListener('keydown',event=>{
    const target=event.target;if(!enabled||!python(target)||event.isComposing)return;
    if(event.key==='Escape'){hide();return;}
    if(event.ctrlKey&&event.code==='Space'){event.preventDefault();event.stopImmediatePropagation();void update(target);return;}
    if(!panel.hidden&&input===target&&analysis?.items.length&&!event.shiftKey){
      if(['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();event.stopImmediatePropagation();selected=(selected+(event.key==='ArrowDown'?1:-1)+analysis.items.length)%analysis.items.length;paint();panel.querySelector('.assist-item.selected')?.scrollIntoView({block:'nearest'});return;}
      if(event.key==='Tab'||event.key==='Enter'){event.preventDefault();event.stopImmediatePropagation();apply(selected);return;}
    }
    if(event.key==='('&&target.selectionStart===target.selectionEnd&&!core.scan(target.value,target.selectionStart).blocked){event.preventDefault();event.stopImmediatePropagation();const start=target.selectionStart;target.setRangeText('()',start,start,'end');target.setSelectionRange(start+1,start+1);target.dispatchEvent(new Event('input',{bubbles:true}));void update(target);return;}
    if(event.key===')'&&target.selectionStart===target.selectionEnd&&target.value[target.selectionStart]===')'){event.preventDefault();event.stopImmediatePropagation();target.setSelectionRange(target.selectionStart+1,target.selectionStart+1);void update(target);return;}
    if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key))setTimeout(()=>update(target),0);
  },true);
  document.addEventListener('scroll',event=>{if(!panel.hidden&&!panel.contains(event.target))position();},true);window.addEventListener('resize',hide);
  // Opt-in: metadata is not fetched and no model/backend is contacted until enabled.
  return {close:hide};
})();
